331	// CloseItem 在事项所在班次结束前关闭该事项，须填写操作人。
332	func (svc *Service) CloseItem(itemID, operator string) (Item, error) {
333		itemID = clean(itemID)
334		operator = clean(operator)
335		if err := requireNonEmpty("操作人", operator); err != nil {
336			return Item{}, err
337		}
338	
339		var closed Item
340		err := svc.store.mutate(func(d *Data) error {
341			it, _ := findItem(d, itemID)
342			if it == nil {
343				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
344			}
345			if it.Closed {
346				return fmt.Errorf("%w：事项 %s 已关闭，不能重复关闭", ErrHandoverState, itemID)
347			}
348			sh, _ := findShift(d, it.CurrentShiftID)
349			if sh == nil || sh.Closed {
350				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，关闭状态不能修改",
351					ErrShiftClosed, itemID, it.CurrentShiftID)
352			}
353			now := svc.now()
354			it.Closed = true
355			it.ClosedAt = &now
356			it.CloseOperator = operator
357			it.Events = append(it.Events, ItemEvent{At: now, Kind: "closed", Operator: operator})
358			closed = *it
359			return nil
360		})
361		return closed, err
362	}
