520	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
521	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
522	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
523	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
524	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
525		handoverID = clean(handoverID)
526		itemID = clean(itemID)
527		operator = clean(operator)
528		reason = clean(reason)
529		trackingNote = clean(trackingNote)
530		nextFollowOwner = clean(nextFollowOwner)
531	
532		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
533			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
534		}
535		if err := requireNonEmpty("操作人", operator); err != nil {
536			return Handover{}, err
537		}
538	
539		var result Handover
540		err := svc.store.mutate(func(d *Data) error {
541			h, _ := findHandover(d, handoverID)
542			if h == nil {
543				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
544			}
545			e, _ := findEntry(h, itemID)
546			if e == nil {
547				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
548			}
549			if e.Status.Received() {
550				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
551					ErrHandoverState, e.ItemID, e.Status.Label())
552			}
553			if e.Status == EntryReturned {
554				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
555				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
556				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
557				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
558					ErrHandoverState, e.ItemID, h.ID)
559			}
560			switch action {
561			case ActionReturn:
562				if err := requireNonEmpty("退回原因", reason); err != nil {
563					return err
564				}
565			case ActionTrack:
566				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
567					return err
568				}
569				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
570					return err
571				}
572			}
573	
574			now := svc.now()
575			switch action {
576			case ActionConfirm:
577				e.Status = EntryConfirmed
578			case ActionTrack:
579				e.Status = EntryTracking
580				e.TrackingNote = trackingNote
581				e.FollowOwner = nextFollowOwner
582			case ActionReturn:
583				e.Status = EntryReturned
584				e.Rounds = append(e.Rounds, ReturnRound{
585					Seq:            len(e.Rounds) + 1,
586					ReturnedAt:     now,
587					ReturnOperator: operator,
588					Reason:         reason,
589				})
590			}
591			e.Operator = operator
592			e.ProcessedAt = &now
593	
594			if action != ActionReturn {
595				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
596				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
597					it.CurrentShiftID = h.ToShiftID
598					if !contains(it.ShiftIDs, h.ToShiftID) {
599						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
600					}
601					detail := "接班班次 " + h.ToShiftID + " 接收：" + e.Status.Label()
602					if action == ActionTrack {
603						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
604						it.FollowOwner = nextFollowOwner
605						detail += "；跟踪说明：" + trackingNote + "；后续负责人：" + nextFollowOwner
606					}
607					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
608				}
609			}
610	
611			if h.Completed() && h.CompletedAt == nil {
612				h.CompletedAt = &now
613			}
614			result = *h
615			return nil
616		})
617		return result, err
618	}
619	
620	func contains(xs []string, x string) bool {
621		for _, v := range xs {
622			if v == x {
623				return true
624			}
625		}
626		return false
627	}
628	
629	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
630	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
631	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
632	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
633	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
634	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
635	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
636		handoverID = clean(handoverID)
637		itemID = clean(itemID)
638		operator = clean(operator)
639		supplement = clean(supplement)
640		if err := requireNonEmpty("操作人", operator); err != nil {
641			return Handover{}, err
642		}
643		if err := requireNonEmpty("补充说明", supplement); err != nil {
644			return Handover{}, err
645		}
646	
647		var result Handover
648		err := svc.store.mutate(func(d *Data) error {
649			h, _ := findHandover(d, handoverID)
650			if h == nil {
651				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
652			}
653			e, _ := findEntry(h, itemID)
654			if e == nil {
655				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
656			}
657			if e.Status != EntryReturned {
658				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
659					ErrHandoverState, e.ItemID, e.Status.Label())
660			}
661			if len(e.Rounds) == 0 {
662				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
663			}
664			round := &e.Rounds[len(e.Rounds)-1]
665			if round.ResubmittedAt != nil {
666				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
667			}
668			now := svc.now()
669			round.Supplement = supplement
670			round.SupplementOperator = operator
671			round.SupplementAt = &now
672			round.ResubmittedAt = &now
673			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
674			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
675			e.Status = EntryPending
676			e.Operator = ""
677			e.ProcessedAt = nil
678			result = *h
679			return nil
680		})
681		return result, err
682	}
