237	// FormatHandover 格式化完整交接记录。
238	func FormatHandover(h Handover) string {
239		var b strings.Builder
240		state := "未完成"
241		if h.Completed() {
242			state = "已完成 " + fmtTimePtr(h.CompletedAt)
243		}
244		fmt.Fprintf(&b, "%s  岗位=%s  %s -> %s  发起于 %s  [%s]  共%d项\n",
245			h.ID, h.Position, h.FromShiftID, h.ToShiftID, fmtTime(h.CreatedAt), state, len(h.Entries))
246		if len(h.Entries) == 0 {
247			b.WriteString("  （空清单，直接完成）\n")
248		}
249		for i := range h.Entries {
250			b.WriteString(indentLines(FormatEntry(h.Entries[i]), "  "))
251		}
252		return b.String()
253	}
254	
255	func indentLines(s, prefix string) string {
256		return prefix + strings.ReplaceAll(strings.TrimRight(s, "\n"), "\n", "\n"+prefix) + "\n"
257	}
258	
259	// FormatReport 格式化按班次查询的完整报告。
260	func FormatReport(rep ShiftReport) string {
261		var b strings.Builder
262		b.WriteString("班次 " + FormatShift(rep.Shift) + "\n")
263	
264		b.WriteString("\n重叠说明：\n")
265		if len(rep.OverlapNotes) == 0 {
266			b.WriteString("  （无）\n")
267		}
268		for _, n := range rep.OverlapNotes {
269			b.WriteString(indentLines(FormatOverlapNote(n), "  "))
270		}
271	
272		if rep.ItemsAtClose {
273			b.WriteString("\n事项（以下为结束时记录，冻结于该班结束成功时刻；后班的修改、关闭与交接不改变本记录）：\n")
274			if len(rep.CloseItems) == 0 {
275				b.WriteString("  （结束时没有事项）\n")
276			}
277			for _, s := range rep.CloseItems {
278				var latest *Item
279				if v, ok := rep.LatestItems[s.ItemID]; ok {
280					latest = &v
281				}
282				b.WriteString(indentLines(FormatCloseItem(s, latest), "  "))
283			}
284		} else {
285			if rep.HistoryIncomplete {
286				b.WriteString("\n事项（历史记录不完整，该班结束时未留下记录，以下为当前信息，不能视为结束时事实）：\n")
287			} else {
288				b.WriteString("\n事项：\n")
289			}
290			if len(rep.Items) == 0 {
291				b.WriteString("  （无）\n")
292			}
293			for _, it := range rep.Items {
294				b.WriteString(indentLines(FormatItem(it), "  "))
295			}
296		}
297	
298		b.WriteString("\n交班对象：\n")
299		if rep.Outgoing == nil {
300			b.WriteString("  （尚未发起交接）\n")
301		} else {
302			b.WriteString(indentLines(FormatHandover(*rep.Outgoing), "  "))
303		}
304	
305		b.WriteString("\n接班交接：\n")
306		if len(rep.Incoming) == 0 {
307			b.WriteString("  （无）\n")
308		}
309		for _, h := range rep.Incoming {
310			b.WriteString(indentLines(FormatHandover(h), "  "))
311		}
312	
313		b.WriteString("\n各项交接当前结果：\n")
314		if len(rep.Results) == 0 {
315			b.WriteString("  （无）\n")
316		}
317		ids := make([]string, 0, len(rep.Results))
318		for id := range rep.Results {
319			ids = append(ids, id)
320		}
321		sort.Strings(ids)
322		for _, id := range ids {
323			views := rep.Results[id]
324			for _, v := range views {
325				operator, processedAt := dashIfEmpty(v.Entry.Operator), fmtTimePtr(v.Entry.ProcessedAt)
326				if v.Entry.ProcessedAt == nil {
327					operator, processedAt = "尚未处理", "尚未处理"
328				}
329				fmt.Fprintf(&b, "  事项 %s 交接 %s（%s -> %s）当前结果：%s；处理人=%s；处理时间=%s\n",
330					id, v.HandoverID, v.FromShift, v.ToShift,
331					v.Entry.Status.Label(), operator, processedAt)
332				for _, r := range v.Entry.Rounds {
333					fmt.Fprintf(&b, "    第%d次退回：操作人=%s 时间=%s 原因=%s\n",
334						r.Seq, r.ReturnOperator, fmtTime(r.ReturnedAt), r.Reason)
335					if r.Supplement != "" {
336						fmt.Fprintf(&b, "      补充：%s（补充人=%s，补充时间=%s）\n",
337							r.Supplement, dashIfEmpty(r.SupplementOperator), fmtTimePtr(r.SupplementAt))
338					}
339					if r.ResubmittedAt != nil {
340						fmt.Fprintf(&b, "      已重新提交：%s\n", fmtTime(*r.ResubmittedAt))
341					}
342				}
343			}
344		}
345		return b.String()
346	}
